// McpShellLexerInit initializes any static state used to implement McpShellLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewMcpShellLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func McpShellLexerInit() {
	staticData := &McpShellLexerLexerStaticData
	staticData.once.Do(mcpshelllexerLexerInit)
}

// NewMcpShellLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewMcpShellLexer(input antlr.CharStream) *McpShellLexer {
	McpShellLexerInit()
	l := new(McpShellLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &McpShellLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "McpShellLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

